/// The factory-wide spend ceiling. Distinct from Fuel, which bounds one itinerary: a
/// scheduled pipeline mints a fresh itinerary with a fresh Fuel budget on every tick, so
/// only the Reserve bounds the total. The window rolls rather than resetting at midnight.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ReserveState {
    /// Ceiling for the window. Null when no ceiling is enforced.
    #[serde(default)]
    pub cap_usd: Option<f64>,
    /// True when the Reserve is currently refusing new work.
    pub exhausted: bool,
    /// Left before new work is refused. Null when unlimited.
    #[serde(default)]
    pub remaining_usd: Option<f64>,
    /// Spend within the current window.
    pub spent_usd: f64,
    /// How far back the rolling window reaches.
    pub window_hours: i64,
}

/// Which open help requests to mark as dealt with.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ResolveHelpRequest {
    /// Only requests from this agent.
    #[serde(default)]
    pub agent: Option<String>,
    /// Only requests of this kind.
    #[serde(default)]
    pub blocker: Option<Blocker>,
    /// Only requests raised by this run. The narrowest form, and the one a list with a button
    /// beside each row uses.
    #[serde(default)]
    pub run_id: Option<String>,
    /// How far back to look. Defaults to the last 30 days.
    #[serde(default)]
    pub window: Option<CostWindow>,
}

/// One entry of the route map, possibly expanding to several edges.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Route {
    /// Sending agents.
    pub from: Vec<String>,
    /// Set when flights on this edge are parked at a rendezvous barrier.
    #[serde(default)]
    pub join: Option<Join>,
    /// The pipelines whose chains may use this route. Null for a global route, which every
    /// chain may use — what every route meant before scopes existed.
    #[serde(default)]
    pub pipelines: Option<Vec<String>>,
    /// Backstop for a barrier that never completes.
    #[serde(default)]
    pub timeout_sec: Option<i64>,
    /// Receiving agents.
    pub to: Vec<String>,
}

/// The factory drawn as a graph.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RouteMap {
    /// Which file it was generated from.
    #[serde(default)]
    pub config_path: Option<String>,
    /// When the configuration was read.
    pub generated_at: String,
    /// Mermaid `flowchart` source, ready to render.
    pub mermaid: String,
}

/// One supervised CLI execution.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Run {
    /// Which agent was run.
    pub agent: String,
    /// What the run could not get past, when it asked for help. Independent of `status`: an
    /// agent can finish its task and still have been unable to check something. Without it a
    /// blocked run looks exactly like a clean one on a list.
    #[serde(default)]
    pub blocked_on: Option<String>,
    /// The context-window tier the run's command line chose, such as `long_context`. Null
    /// when it chose none, and for runs recorded before Layover kept it.
    #[serde(default)]
    pub context: Option<String>,
    /// Where `cost_usd` came from.
    pub cost_source: CostSource,
    /// Null when the runner reported no cost, which the Tower logs loudly.
    #[serde(default)]
    pub cost_usd: Option<f64>,
    /// Why the run ended, for the outcomes where that is not self-evident. For a failure, how
    /// the process exited and the line of its output most likely to say why — picked from the
    /// transcript, redacted and capped — so a run that failed in one second says what it
    /// said without anybody opening its Hangar.
    #[serde(default)]
    pub detail: Option<String>,
    /// How long the run took. Null while it is still going, and also null if the clock moved
    /// backwards between the two readings — a negative duration on a dashboard is worse than
    /// an absent one, because somebody will average it.
    #[serde(default)]
    pub duration_sec: Option<i64>,
    /// Process exit code, when the process exited on its own and the platform reported one.
    /// Null for a run still going, one that never started, and one the Tower ended for a
    /// timeout or a Ground Stop.
    #[serde(default)]
    pub exit_code: Option<i32>,
    /// When the process exited; null while it is still running.
    #[serde(default)]
    pub finished_at: Option<String>,
    /// The flags the run was composed with, for a chain a workflow opened. Absent otherwise,
    /// and for runs recorded before they were kept.
    #[serde(default)]
    pub flags: Option<std::collections::BTreeMap<String, bool>>,
    /// Hops left when this run was started, mirrored for display only.
    #[serde(default)]
    pub hops_remaining: Option<i32>,
    /// The chain this run belongs to.
    pub itinerary_id: String,
    /// Which model the runner used, when it said.
    #[serde(default)]
    pub model: Option<String>,
    /// The pipeline that started this run's chain, when one did.
    #[serde(default)]
    pub pipeline: Option<String>,
    /// The reasoning effort the run's command line gave the model — from the agent's
    /// `effort`, `[defaults]`, or a value its runner fixes. Null when the command line set
    /// none, and for runs recorded before Layover kept it.
    #[serde(default)]
    pub reasoning_effort: Option<String>,
    /// Identifier of this run.
    pub run_id: String,
    /// The agents whose flights started this run — for a released join, every arrival. Empty
    /// when the work came from outside the mesh: a person, a schedule or a resumed layover.
    /// Absent when it was not recorded: by an earlier release, for a join restarted after the
    /// Tower that released it went away, or for a run the Reserve refused.
    #[serde(default)]
    pub sent_by: Option<Vec<String>>,
    /// When the process was spawned.
    pub started_at: String,
    /// How it ended, or that it has not.
    pub status: RunStatus,
}

/// Matching runs, newest first.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct RunList {
    /// The runs.
    pub runs: Vec<Run>,
}

/// How a run ended, or that it has not.
///
/// `halted` is deliberately distinct from `failed`: a rail stopping work — Hops, Fuel, the
/// run cap or the Reserve — is the system doing its job, and colouring it like a crash
/// teaches people to ignore the colour. `interrupted` means the run was alive when the Tower
/// went away; it is recoverable, and recovery starts a new run rather than resuming this one.
///
/// There is no `stalled` here. Stalling is something an *itinerary* does when it parks at a
/// barrier that never releases; a run either finishes or does not.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum RunStatus {
    /// `running`
    #[serde(rename = "running")]
    Running,
    /// `succeeded`
    #[serde(rename = "succeeded")]
    Succeeded,
    /// `failed`
    #[serde(rename = "failed")]
    Failed,
    /// `timed_out`
    #[serde(rename = "timed_out")]
    TimedOut,
    /// `halted`
    #[serde(rename = "halted")]
    Halted,
    /// `interrupted`
    #[serde(rename = "interrupted")]
    Interrupted,
}

/// One tick of a scheduled pipeline.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ScheduledFire {
    /// When it is due.
    pub at: String,
    /// For a resuming tick, the layovers expected to be picked up by it.
    pub collects: i32,
    /// The pipeline's previous wave is still going, so this tick is skipped unless that
    /// finishes first. Only ever the next tick: what is running later is not known now.
    pub may_skip: bool,
    /// It is already due and has not fired: held by a Ground Stop, or by a Tower busy starting
    /// work. It fires as soon as it can, and the ticks after it count from then.
    pub overdue: bool,
    /// The pipeline that fires.
    pub pipeline: String,
    /// It collects due layovers rather than starting fresh work.
    pub resumes: bool,
}

/// One scheduled pipeline, and when it next fires.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ScheduledWorkflow {
    /// How many ticks are due before `until`. Counted whole up to 10,000; `fires` lists at most
    /// 24 of them, so a one-minute schedule does not bury every other.
    pub fires_in_window: i32,
    /// The most recent of those, if any.
    #[serde(default)]
    pub last_skipped_at: Option<String>,
    /// When its next tick is due, by the Tower's clock. Null when no clock is known in this
    /// process, or for a cron expression that never matches. A time already past is a tick
    /// held back — by a Ground Stop, usually — that fires as soon as it can.
    #[serde(default)]
    pub next_at: Option<String>,
    /// True when it sets `overlap = "allow"`, so a tick starts whatever is running.
    pub overlaps: bool,
    /// The pipeline.
    pub pipeline: String,
    /// True when its ticks collect due layovers rather than starting fresh work.
    pub resumes: bool,
    /// Ticks of it skipped in the last seven days.
    pub skipped_7d: i32,
    /// Its previous wave is queued or running now. Unless that finishes first, its next tick
    /// is skipped.
    pub working: bool,
}

/// Exactly one of `pipeline` and `to` must be given, and flags are only accepted alongside a
/// pipeline, because a pipeline is what declares them.
///
/// Neither is marked required here because JSON Schema cannot state "exactly one of these"
/// in a way this generator supports. The Tower enforces it and answers `400` — so a client
/// that satisfies this schema can still be rejected.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SendFlightRequest {
    /// What the receiving agent is being asked to do.
    pub body: String,
    /// Flag overrides, keyed by flag name. Unset flags take their declared default.
    #[serde(default)]
    pub flags: Option<std::collections::BTreeMap<String, bool>>,
    /// Name of the pipeline to start.
    #[serde(default)]
    pub pipeline: Option<String>,
    /// Name of an `entry = true` agent to send to directly.
    #[serde(default)]
    pub to: Option<String>,
}

/// Why a scheduled tick that came due did not start. `still_working`: the pipeline's previous
/// wave was still queued or running, and it does not set `overlap = "allow"`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum SkipReason {
    /// `still_working`
    #[serde(rename = "still_working")]
    StillWorking,
}

/// A scheduled tick that came due and did not start.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct SkippedTick {
    /// When the Tower decided not to start it.
    pub at: String,
    /// The pipeline whose tick it was.
    pub pipeline: String,
    /// Why.
    pub reason: SkipReason,
}

/// Liveness of the Tower itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Status {
    /// `ok`
    #[serde(rename = "ok")]
    Ok,
}

/// Tokens consumed. Cached reads and writes are counted apart from fresh input because
/// providers price them very differently, and blending them makes any derived cost wrong by
/// whatever the cache hit rate happened to be.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct TokenUsage {
    /// Tokens served from the provider's prompt cache.
    pub cache_read: i64,
    /// Tokens written into the provider's prompt cache.
    pub cache_write: i64,
    /// Prompt tokens billed at the input rate.
    pub input: i64,
    /// Generated tokens.
    pub output: i64,
}

/// What starts a pipeline.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Trigger {
    /// Set when the pipeline fires on a five-field cron expression.
    #[serde(default)]
    pub cron: Option<String>,
    /// Set when the pipeline fires on a fixed interval.
    #[serde(default)]
    pub every_seconds: Option<i64>,
    /// Whether a human or a clock starts this pipeline.
    pub kind: TriggerKind,
}

/// Whether a human or a clock starts a pipeline.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum TriggerKind {
    /// `manual`
    #[serde(rename = "manual")]
    Manual,
    /// `scheduled`
    #[serde(rename = "scheduled")]
    Scheduled,
}

/// What will start on its own within a window, and the ticks that recently did not.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Upcoming {
    /// What keeps the schedule: the Tower in this process. Null when nothing here does
    /// (`--watch-only`): when ticks fall is then unknown, and `fires` is empty.
    #[serde(default)]
    pub clock: Option<String>,
    /// Ticks due before `until`, soonest first, at most 24 per pipeline.
    pub fires: Vec<ScheduledFire>,
    /// A Ground Stop is engaged, so nothing here fires until it is released.
    pub ground_stop: bool,
    /// Layovers waiting to be picked up, soonest due first.
    pub layovers: Vec<WaitingLayover>,
    /// The moment this was worked out, so "in 20 minutes" is measured from it.
    pub now: String,
    /// Ticks skipped in the last seven days, most recent first, at most 100.
    pub skips: Vec<SkippedTick>,
    /// The end of the window.
    pub until: String,
    /// Every pipeline with a schedule, by name.
    pub workflows: Vec<ScheduledWorkflow>,
}

/// Work an agent set down to be picked up later, and when it will be.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WaitingLayover {
    /// The agent the resumed work goes to.
    pub agent: String,
    /// When it was set down.
    pub booked_at: String,
    /// The chain that set it down.
    pub booked_by: String,
    /// The first tick of a resuming pipeline at or after `due_at`, which is when it will be
    /// picked up unless that tick is skipped. Null when no clock is known in this process, or
    /// when no scheduled pipeline `resumes` — then nothing will ever pick it up.
    #[serde(default)]
    pub collected_at: Option<String>,
    /// The resuming pipeline whose tick that is.
    #[serde(default)]
    pub collected_by: Option<String>,
    /// The soonest it may be picked up.
    pub due_at: String,
    /// Identifier of the layover.
    pub layover_id: String,
    /// The workflow that chain belonged to, when that was recorded.
    #[serde(default)]
    pub pipeline: Option<String>,
    /// What it is waiting for, in the words of the agent that set it down.
    pub waiting_for: String,
}

/// A resolved window, and an honest account of how it was arrived at.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct WindowSpan {
    /// True when the start was reckoned against a local midnight.
    pub calendar: bool,
    /// When the period ends, which is the moment it was resolved.
    pub end: String,
    /// A human label, such as "Last 30 days".
    pub label: String,
    /// When the period begins. Null means from the beginning of what is kept.
    #[serde(default)]
    pub start: Option<String>,
    /// True when the period reaches further back than retention keeps, which makes the
    /// totals a lower bound rather than a total.
    pub truncated: bool,
    /// Which window this is.
    pub window: CostWindow,
    /// The IANA zone the start was reckoned in, or null for a rolling window. The absence is
    /// the point: nobody should have to wonder which zone "last 7 days" used.
    #[serde(default)]
    pub zone: Option<String>,
}

/// Whether instances of one pipeline are declared to share a working directory or to get one
/// each. `per-itinerary` is declared, not yet enforced: every instance still works in the
/// shared working directory.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Workspace {
    /// `shared`
    #[serde(rename = "shared")]
    Shared,
    /// `per-itinerary`
    #[serde(rename = "per-itinerary")]
    PerItinerary,
}

/// query parameters for `getCosts`.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct GetCostsQuery {
    /// The period to total over. Defaults to the last 30 days.
    ///
    /// Note that `today` and `month_to_date` are *calendar* windows and the rest are *rolling* ones.
    /// A rolling window is the same length everywhere; a calendar one begins at local
    /// midnight and therefore depends on where the Tower is standing. The response says
    /// which zone was used, so the figure can be read without having to guess.
    #[serde(default)]
    pub window: Option<CostWindow>,
    /// Narrow the totals, the per-agent and the per-model breakdowns to one workflow.
    ///
    /// `reserve` is deliberately unaffected. The Reserve caps the whole factory, so reporting
    /// it against one workflow's spend would describe a rail that does not exist.
    #[serde(default)]
    pub pipeline: Option<String>,
}

