/// Everything the Tower must implement to serve this API.
///
/// One method per `operationId`. Adding an operation to `api/openapi.yaml` adds a method
/// here, so an unimplemented endpoint is a compile error rather than a 404 discovered in
/// production.
pub trait Api: Send + Sync + 'static {
    /// Every configured agent and the route map between them.
    ///
    /// This is the UI's graph view, and it is also how a human answers "what can talk to what"
    /// without reading the TOML.
    ///
    /// `GET /agents`
    fn list_agents(&self) -> impl core::future::Future<Output = Result<AgentList, Problem>> + Send;
    /// What the factory has spent, and how much of that is measured.
    ///
    /// A single Fuel figure says whether a chain may continue. This says where the money went —
    /// per agent, per model — and, critically, how much of the total the runners actually
    /// reported rather than Layover inferring it from a rate card.
    ///
    /// Treat `confidence` as part of the number. A total that is mostly measured is still not
    /// measured, so any estimated or unreported run downgrades the whole figure.
    ///
    /// `GET /costs`
    fn get_costs(
        &self,
        query: GetCostsQuery,
    ) -> impl core::future::Future<Output = Result<CostReport, Problem>> + Send;
    /// Flights waiting for something to dispatch them.
    ///
    /// Work that has been asked for and not yet started. Until the supervisor exists this is
    /// everything anybody has triggered; afterwards it is the backlog.
    ///
    /// `GET /flights`
    fn list_pending(
        &self,
    ) -> impl core::future::Future<Output = Result<PendingList, Problem>> + Send;
    /// Start work by sending the first flight of a new itinerary.
    ///
    /// Give either a `pipeline` or a `to`. A pipeline is the normal way in: it names the entry
    /// agent and declares which flags may be set. A bare `to` sends to an agent marked
    /// `entry = true` and accepts no flags.
    ///
    /// **The flight is queued, not run.** `202` means the work is booked and durable; a Tower starts
    /// it as soon as a slot is free. `GET /flights` shows what is waiting, and which Tower will
    /// start it.
    ///
    /// `POST /flights`
    fn send_flight(
        &self,
        body: SendFlightRequest,
    ) -> impl core::future::Future<Output = Result<FlightAccepted, Problem>> + Send;
    /// Take a queued flight back off the queue.
    ///
    /// Only work that has not started can be cancelled. A run that is already going is stopped
    /// with a Ground Stop, which is a different decision with a different blast radius — one
    /// flight versus the whole factory — and conflating them would make the smaller action feel
    /// as dangerous as the larger one.
    ///
    /// `DELETE /flights/{flight_id}`
    fn cancel_flight(
        &self,
        path: CancelFlightPath,
    ) -> impl core::future::Future<Output = Result<PendingList, Problem>> + Send;
    /// The route map as a diagram, with what is happening drawn on it.
    ///
    /// Mermaid source, generated from the configuration as it is on disk right now. Edit
    /// `layover.toml` and reload; the diagram changes with it, because nothing here is baked at
    /// build time.
    ///
    /// Agents currently running, waiting at a barrier, or freshly failed are coloured. An agent
    /// with more than one run alive at once — the same workflow triggered twice, say — carries a
    /// count such as `×2`. An edge into a joined agent from a sender the barrier does not name is
    /// drawn as bypassing it, which is what actually happens. To see one chain on its own, use
    /// `GET /itineraries/{itinerary_id}`.
    ///
    /// `GET /graph`
    fn get_graph(
        &self,
        query: GetGraphQuery,
    ) -> impl core::future::Future<Output = Result<RouteMap, Problem>> + Send;
    /// Halt everything.
    ///
    /// Ground Stop is a file on disk rather than in-memory state, so it survives a Tower crash
    /// and can be set by hand when nothing else is responding.
    ///
    /// `POST /ground-stop`
    fn engage_ground_stop(
        &self,
    ) -> impl core::future::Future<Output = Result<GroundStop, Problem>> + Send;
    /// Resume.
    ///
    /// `DELETE /ground-stop`
    fn release_ground_stop(
        &self,
    ) -> impl core::future::Future<Output = Result<GroundStop, Problem>> + Send;
    /// Liveness, version and whether a Ground Stop is engaged.
    ///
    /// `GET /health`
    fn get_health(&self) -> impl core::future::Future<Output = Result<Health, Problem>> + Send;
    /// What agents are stuck on.
    ///
    /// A lights-out factory's worst failure is not a crash — a crash is loud. It is an agent that
    /// quietly cannot do what it was asked, produces something plausible anyway, and passes it
    /// downstream. This is the channel that stops that being invisible.
    ///
    /// Measured against a working prototype, five of six requests were permission or access
    /// failures, so `access` is worth filtering for first.
    ///
    /// `GET /help`
    fn list_help(
        &self,
        query: ListHelpQuery,
    ) -> impl core::future::Future<Output = Result<HelpList, Problem>> + Send;
    /// Answer a help request, and continue the work it stopped.
    ///
    /// Answers every open request the run raised. Queues a flight to the agent that asked, from a
    /// person, starting a **new chain** with a fresh budget — the chain that asked is over — in
    /// the same workflow, with the same flags and the same routes as the chain that asked. Never
    /// the workflow's defaults: continuing a chain that was allowed to publish as one that may not
    /// is the silent downgrade this exists to avoid.
    ///
    /// The agent is told `In reply to your help request <run_id> (<summary>)`, then the body,
    /// verbatim. The requests are marked dealt with, recording who replied, what they said and the
    /// new chain, which records the chain it continues.
    ///
    /// A request filed before Layover recorded its chain's flags does not know them. For one of
    /// those whose workflow declares flags, `flags` must say what they were, and the reply is
    /// refused with `409` until it does. For any other request `flags` is refused: the recorded
    /// flags are carried, and continuing a chain with different ones is what `POST /flights`
    /// is for.
    ///
    /// Needs the same token as a trigger, and a Ground Stop refuses it like one.
    ///
    /// `POST /help/reply`
    fn reply_help(
        &self,
        body: HelpReplyRequest,
    ) -> impl core::future::Future<Output = Result<HelpReplied, Problem>> + Send;
    /// Mark help requests as dealt with.
    ///
    /// Resolving says *the blocker is gone*, not *I have read this*. An agent that raises the same
    /// problem on its next run will raise it again, which is the point: a list that clears itself
    /// on being looked at stops being evidence of anything.
    ///
    /// Narrow by agent, blocker or run. An empty body resolves every open request in the window,
    /// which is what you want after fixing something that stopped everything.
    ///
    /// `POST /help/resolve`
    fn resolve_help(
        &self,
        body: ResolveHelpRequest,
    ) -> impl core::future::Future<Output = Result<HelpResolved, Problem>> + Send;
    /// Chains of work, and what became of each.
    ///
    /// A run is one agent doing one thing; an itinerary is the whole causal chain and the budget
    /// it shares. The distinction matters most when something goes wrong: a chain can be *stalled*
    /// — every run in it succeeded and nothing will ever happen again — and a list of runs cannot
    /// show that, because there is no failed run to point at.
    ///
    /// A chain is listed from the moment its first flight is queued: `working`, with no runs yet,
    /// and `queued` naming the agent it waits for. Triggering one workflow several times while
    /// every slot is taken would otherwise show some of those chains and silently not the rest.
    ///
    /// `GET /itineraries`
    fn list_itineraries(
        &self,
        query: ListItinerariesQuery,
    ) -> impl core::future::Future<Output = Result<ItineraryList, Problem>> + Send;
    /// One chain, whole — its runs, what it is waiting for, and its route map.
    ///
    /// Everything one trigger caused, read together: the chain as `GET /itineraries` lists it,
    /// every run in it oldest first with who sent each one, the flights it has queued, and its
    /// workflow's route map coloured by this chain alone.
    ///
    /// Several chains of one workflow run at once, and the workflow's map colours an agent while
    /// *any* of them runs it. This one does not: an agent is `done`, `running`, `failed` or
    /// `queued` for what happened *in this chain*, carries `×2` when it ran twice here, and the
    /// routes the chain's work actually took are marked `travelled`.
    ///
    /// Read from the moment the chain began, whatever its age, as far back as retention keeps.
    ///
    /// `GET /itineraries/{itinerary_id}`
    fn get_itinerary(
        &self,
        path: GetItineraryPath,
    ) -> impl core::future::Future<Output = Result<ItineraryDetail, Problem>> + Send;
    /// What agents have worked out, and how well established it is.
    ///
    /// A learning applies as soon as it is proposed and expires unless later runs arrive at it
    /// independently. There is no approval queue, deliberately: a sibling project built one and
    /// after 22 days held 88 learnings, none ever approved, so not one had ever reached a run.
    ///
    /// A learning becomes permanent through independent rediscovery, which is evidence, rather
    /// than through its `impact` rating, which is the agent's own claim about its own work.
    ///
    /// `GET /learnings`
    fn list_learnings(
        &self,
        query: ListLearningsQuery,
    ) -> impl core::future::Future<Output = Result<LearningList, Problem>> + Send;
    /// Settle a learning, either way.
    ///
    /// **This is not an approval queue.** A learning applies from the moment it is proposed, and
    /// nothing is waiting on you. A sibling project gated learnings behind approval and after 22
    /// days held 88 of them, none ever approved, so not one had ever reached a run.
    ///
    /// This is the override. `confirmed` means "this is real, keep it indefinitely" and spares it
    /// from lapsing. `rejected` means "this is wrong, stop applying it" and takes it out of every
    /// future run. Both are judgements a person makes about something already in use, not
    /// permission for it to start being used.
    ///
    /// `PATCH /learnings/{learning_id}`
    fn judge_learning(
        &self,
        path: JudgeLearningPath,
        body: JudgeLearningRequest,
    ) -> impl core::future::Future<Output = Result<Learning, Problem>> + Send;
    /// Every declared pipeline, its trigger and the flags it accepts.
    ///
    /// `GET /pipelines`
    fn list_pipelines(
        &self,
    ) -> impl core::future::Future<Output = Result<PipelineList, Problem>> + Send;
    /// Runs, live and historical.
    ///
    /// Runs alive now come first, as `running`, from the live records the Tower keeps while a run
    /// is going — whichever process started it. History holds a run only once it has ended.
    ///
    /// `GET /runs`
    fn list_runs(
        &self,
        query: ListRunsQuery,
    ) -> impl core::future::Future<Output = Result<RunList, Problem>> + Send;
    /// One run, including how it ended.
    ///
    /// `GET /runs/{run_id}`
    fn get_run(
        &self,
        path: GetRunPath,
    ) -> impl core::future::Future<Output = Result<Run, Problem>> + Send;
    /// What the agent wrote about this run.
    ///
    /// A transcript is not a report: it contains every approach the agent abandoned, and reading
    /// one to find out what happened is slower than doing the work again. This is the agent''s own
    /// account of what it concluded.
    ///
    /// `GET /runs/{run_id}/report`
    fn get_report(
        &self,
        path: GetReportPath,
    ) -> impl core::future::Future<Output = Result<Report, Problem>> + Send;
    /// What a run's CLI printed, rendered as a terminal would show it, live.
    ///
    /// Read-only. Follows the run's transcript in its Hangar from the start — or from `after` —
    /// and keeps following it while the run is alive. For a run that is over it sends the whole
    /// transcript and closes, so the same request replays how a finished run reached its
    /// conclusion.
    ///
    /// The transcript is rendered rather than sent raw: a Copilot or Claude Code run writes one
    /// JSON event per line, most of them token-by-token deltas of text that arrives again whole.
    /// What is sent is what the CLI would show a person — the prompt's first lines, reasoning,
    /// each tool call and a few lines of what it returned, what the agent said — redacted like a
    /// failure detail and cut to size. Output in no known dialect is sent as written.
    ///
    /// Three events, each with an `id` saying how far the transcript was read:
    ///
    /// - `entry` — `{"kind", "text", "at", "closes"}`. `kind` is one of `prompt`, `think`,
    ///   `say`, `tool`, `done`, `failed`, `info`, `raw`. `at` is when the CLI said it happened,
    ///   or null. `closes` names the partial this entry finishes, or is null.
    /// - `partial` — `{"id", "kind", "text"}`: the end of text still arriving. Empty `text` takes
    ///   it away.
    /// - `end` — `{"status", "detail"}` from history, once the run is over; `"missing": true`
    ///   when no transcript was kept. Sent once, last.
    ///
    /// `GET /runs/{run_id}/stream`
    fn stream_run(
        &self,
        path: StreamRunPath,
        query: StreamRunQuery,
    ) -> impl core::future::Future<Output = Result<EventStream, Problem>> + Send;
    /// What will start on its own, and the scheduled ticks that did not.
    ///
    /// Work nobody has to trigger: every tick of a scheduled pipeline due within the window, and
    /// every layover waiting to be picked up, with the tick expected to collect it. Beside them,
    /// the ticks skipped in the last seven days because the pipeline's previous wave was still
    /// going — a schedule that skips every tick looks, from its runs alone, like one that is
    /// running fine.
    ///
    /// When a tick comes due is known only to the Tower that keeps the clock, because an `every`
    /// schedule is counted from when that Tower started. A dashboard with no Tower in its process
    /// (`--watch-only`) says so with a null `clock` and lists no ticks, rather than guessing.
    ///
    /// Work already queued is not here: `GET /flights` lists it, oldest first, which is the order
    /// it starts in.
    ///
    /// `GET /upcoming`
    fn get_upcoming(
        &self,
        query: GetUpcomingQuery,
    ) -> impl core::future::Future<Output = Result<Upcoming, Problem>> + Send;
}

/// Builds the axum router for this API.
///
/// Routes come straight from the specification, so a path can only exist here if it
/// exists there.
pub fn router<A: Api>(api: std::sync::Arc<A>) -> axum::Router {
    axum::Router::new()
        .route("/agents", axum::routing::get(handle_list_agents::<A>))
        .route("/costs", axum::routing::get(handle_get_costs::<A>))
        .route(
            "/flights",
            axum::routing::get(handle_list_pending::<A>).post(handle_send_flight::<A>),
        )
        .route(
            "/flights/{flight_id}",
            axum::routing::delete(handle_cancel_flight::<A>),
        )
        .route("/graph", axum::routing::get(handle_get_graph::<A>))
        .route(
            "/ground-stop",
            axum::routing::post(handle_engage_ground_stop::<A>)
                .delete(handle_release_ground_stop::<A>),
        )
        .route("/health", axum::routing::get(handle_get_health::<A>))
        .route("/help", axum::routing::get(handle_list_help::<A>))
        .route("/help/reply", axum::routing::post(handle_reply_help::<A>))
        .route(
            "/help/resolve",
            axum::routing::post(handle_resolve_help::<A>),
        )
        .route(
            "/itineraries",
            axum::routing::get(handle_list_itineraries::<A>),
        )
        .route(
            "/itineraries/{itinerary_id}",
            axum::routing::get(handle_get_itinerary::<A>),
        )
        .route("/learnings", axum::routing::get(handle_list_learnings::<A>))
        .route(
            "/learnings/{learning_id}",
            axum::routing::patch(handle_judge_learning::<A>),
        )
        .route("/pipelines", axum::routing::get(handle_list_pipelines::<A>))
        .route("/runs", axum::routing::get(handle_list_runs::<A>))
        .route("/runs/{run_id}", axum::routing::get(handle_get_run::<A>))
        .route(
            "/runs/{run_id}/report",
            axum::routing::get(handle_get_report::<A>),
        )
        .route(
            "/runs/{run_id}/stream",
            axum::routing::get(handle_stream_run::<A>),
        )
        .route("/upcoming", axum::routing::get(handle_get_upcoming::<A>))
        .with_state(api)
}

async fn handle_list_agents<A: Api>(
    axum::extract::State(api): axum::extract::State<std::sync::Arc<A>>,
) -> axum::response::Response {
    match api.list_agents().await {
        Ok(value) => (axum::http::StatusCode::OK, axum::Json(value)).into_response(),
        Err(problem) => problem.into_response(),
    }
}

